const saveBarcodeLookup = `-- name: SaveBarcodeLookup :exec
INSERT INTO disc_barcode_lookups (barcode, provider, found, payload, fetched_at)
VALUES (?1, ?2, ?3, ?4, CURRENT_TIMESTAMP)
ON CONFLICT (barcode, provider) DO UPDATE
SET found = excluded.found, payload = excluded.payload, fetched_at = excluded.fetched_at
`

type SaveBarcodeLookupParams struct {
	Barcode  string `json:"barcode"`
	Provider string `json:"provider"`
	Found    int64  `json:"found"`
	Payload  string `json:"payload"`
}

func (q *Queries) SaveBarcodeLookup(ctx context.Context, arg SaveBarcodeLookupParams) error {
	_, err := q.db.ExecContext(ctx, saveBarcodeLookup,
		arg.Barcode,
		arg.Provider,
		arg.Found,
		arg.Payload,
	)
	return err
}

